import { createHash } from 'crypto'

export interface ConnectorConfig {
  /** Mailchimp API key (Bearer token). Env var: MAILCHIMP_API_KEY */
  mailchimpApiKey: string
  /** Mailchimp audience/list ID. */
  mailchimpListId: string
  /** Mailchimp datacenter prefix (e.g., 'us1', 'us2', 'us10'). Derived from API key if not provided. */
  mailchimpDatacenter?: string
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface StripeWebhookPayload {
  id: string
  object: string
  api_version: string
  created: number
  data: {
    object: {
      id: string
      object: string
      customer: string
      customer_email: string
      metadata: {
        plan_name: string
      }
      mode: string
      payment_status: string
      status: string
    }
  }
  livemode: boolean
  pending_webhooks: number
  type: string
}

export interface HandleResult {
  mailchimpMemberHash: string
  tagName: string
  tagId: number
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function getDatacenter(apiKey: string, explicit?: string): string {
  if (explicit) return explicit
  const parts = apiKey.split('-')
  return parts.length > 1 ? parts[parts.length - 1] : 'us1'
}

function md5Hash(input: string): string {
  const hash = createHash('md5')
  hash.update(input)
  return hash.digest('hex')
}

function validatePayload(payload: StripeWebhookPayload): void {
  if (!payload.data?.object) {
    throw new Error('Missing data.object in webhook payload')
  }
  const session = payload.data.object
  if (!session.customer_email) {
    throw new Error('Missing customer_email in checkout session')
  }
  if (!session.customer) {
    throw new Error('Missing customer ID in checkout session')
  }
  if (!session.metadata?.plan_name) {
    throw new Error('Missing metadata.plan_name in checkout session')
  }
  if (session.payment_status !== 'paid') {
    throw new Error(`Payment not successful: payment_status=${session.payment_status}`)
  }
  if (session.status !== 'complete') {
    throw new Error(`Checkout session not complete: status=${session.status}`)
  }
  if (payload.type !== 'checkout.session.completed') {
    throw new Error(`Unexpected event type: ${payload.type}`)
  }
}

export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const session = payload.data.object
  const email = session.customer_email.toLowerCase()
  const subscriberHash = md5Hash(email)
  const tagName = session.metadata.plan_name
  const datacenter = getDatacenter(config.mailchimpApiKey, config.mailchimpDatacenter)
  const url = `https://${datacenter}.api.mailchimp.com/3.0/lists/${config.mailchimpListId}/members/${subscriberHash}/tags`

  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.mailchimpApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ tags: [{ name: tagName }] }),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Mailchimp API error (${response.status} ${response.statusText}) at ${url}: ${text}`)
  }

  const result = await response.json() as { tags: Array<{ id: number; name: string }> }
  const addedTag = result.tags?.find(t => t.name === tagName)
  if (!addedTag) {
    throw new Error('Tag not found in Mailchimp response')
  }

  return {
    mailchimpMemberHash: subscriberHash,
    tagName,
    tagId: addedTag.id,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, StripeWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpListId: 'list_123',
      mailchimpDatacenter: 'us1',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.tagName).toBe('pro-plan')
    expect(result.tagId).toBe(1)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url.includes('/tags') && req.method === 'POST') {
        return jsonResponse({ tags: [{ id: 42, name: 'pro-plan', date_added: '2023-01-01T12:00:00+00:00' }] }, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    calls = recordedCalls
    baseConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpListId: 'list_123',
      mailchimpDatacenter: 'us1',
      fetch,
    }
  })

  it('maps fields correctly and calls Mailchimp with expected body', async () => {
    const payload: StripeWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'Customer@Example.COM',
          customer: 'cus_456',
          metadata: { plan_name: 'enterprise-plan' },
        },
      },
    }

    const result = await handle(payload, baseConfig)

    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toContain('/lists/list_123/members/')
    expect(call.url).toContain('/tags')
    expect(call.headers.get('authorization')).toBe('Bearer test-key-us1')
    expect(call.json).toEqual({ tags: [{ name: 'enterprise-plan' }] })
    expect(result.tagName).toBe('enterprise-plan')
    expect(result.tagId).toBe(42)
    expect(result.mailchimpMemberHash).toBeDefined()
  })

  it('uses lowercase email for MD5 hash', async () => {
    const payload: StripeWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'UPPER@EXAMPLE.COM',
        },
      },
    }

    await handle(payload, baseConfig)

    const call = calls[0]
    const hashInUrl = call.url.split('/members/')[1]?.split('/tags')[0]
    expect(hashInUrl).toBeDefined()
    expect(hashInUrl).toBe(hashInUrl?.toLowerCase())
  })

  it('throws when customer_email is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { object: { ...SOURCE_EXAMPLE.data.object, customer_email: undefined as any } },
    }

    await expect(handle(payload as unknown as StripeWebhookPayload, baseConfig))
      .rejects.toThrow('Missing customer_email')
  })

  it('throws when customer ID is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { object: { ...SOURCE_EXAMPLE.data.object, customer: undefined as any } },
    }

    await expect(handle(payload as unknown as StripeWebhookPayload, baseConfig))
      .rejects.toThrow('Missing customer ID')
  })

  it('throws when metadata.plan_name is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { object: { ...SOURCE_EXAMPLE.data.object, metadata: {} } },
    }

    await expect(handle(payload as unknown as StripeWebhookPayload, baseConfig))
      .rejects.toThrow('Missing metadata.plan_name')
  })

