    const payload = {
      ...SOURCE_EXAMPLE,
      data: { object: { ...SOURCE_EXAMPLE.data.object, payment_status: 'unpaid' } },
    }

    await expect(handle(payload as unknown as StripeWebhookPayload, baseConfig))
      .rejects.toThrow('Payment not successful')
  })

