    const payload = {
      ...SOURCE_EXAMPLE,
      data: { object: { ...SOURCE_EXAMPLE.data.object, status: 'open' } },
    }

    await expect(handle(payload as unknown as StripeWebhookPayload, baseConfig))
      .rejects.toThrow('Checkout session not complete')
  })

  it('throws on non-2xx Mailchimp response with status and endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config = { ...baseConfig, fetch }

    await expect(handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config))
      .rejects.toThrow(/Mailchimp API error \(401 Unauthorized\) at .*\/tags/)
    expect(errorCalls.length).toBe(1)
  })

  it('derives datacenter from API key when not explicitly provided', async () => {
    const { fetch, calls: dcCalls } = fakeFetch((req) => {
      if (req.url.includes('us10.api.mailchimp.com')) {
        return jsonResponse({ tags: [{ id: 1, name: 'pro-plan' }] }, 200)
      }
      return jsonResponse({ error: 'wrong dc' }, 404)
    })
    const config: ConnectorConfig = {
      mailchimpApiKey: 'key-us10',
      mailchimpListId: 'list_123',
      fetch,
    }

    await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config)

    expect(dcCalls[0].url).toContain('us10.api.mailchimp.com')
  })

  it('uses explicit datacenter over API key derivation', async () => {
    const { fetch, calls: dcCalls } = fakeFetch((req) => {
